package ru.fastgo.tsd;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;
public class ScanDocumentTest {
 @Test public void repairQrIsRecognizedInSaleModeButForeignAndProductCodesAreNot(){assertTrue(ScanDocument.isRepairCode("https://ivankirillov414-art.github.io/fastgo-control/workshop.html#order?kind=repair&id=test"));assertTrue(ScanDocument.isRepairCode("https://ivankirillov414-art.github.io/fastgo-control/repair-status.html#token"));assertFalse(ScanDocument.isRepairCode("https://evil.test/fastgo-control/workshop.html#order?kind=repair&id=test"));assertFalse(ScanDocument.isRepairCode("FGP-00000001"));}
 private JSONObject part()throws Exception{return new JSONObject().put("id","part-1").put("name","Камера");}
 @Test public void deliberateRescanCountsButSerializationDoesNot()throws Exception{JSONObject d=ScanDocument.create("receipt");ScanDocument.append(d,"code",part());ScanDocument.append(d,"code",part());assertEquals(2,ScanDocument.items(d).getJSONObject(0).getInt("quantity"));JSONObject retry=new JSONObject(d.toString());assertEquals(d.getString("id"),retry.getString("id"));assertEquals(d.getInt("revision"),retry.getInt("revision"));assertNotEquals(d.getJSONArray("events").getJSONObject(0).getString("id"),d.getJSONArray("events").getJSONObject(1).getString("id"));}
 @Test public void unknownAndUndoSurviveRestart()throws Exception{JSONObject d=ScanDocument.create("receipt");ScanDocument.append(d,"unknown",null);JSONObject restored=new JSONObject(d.toString());assertEquals("unknown",ScanDocument.last(restored).getString("code"));assertEquals(0,ScanDocument.items(restored).length());assertTrue(ScanDocument.undo(restored));assertNull(ScanDocument.last(restored));assertEquals(0,ScanDocument.count(restored));}
 @Test public void scansDuringLaptopCommitCarryToNextDocument()throws Exception{JSONObject d=ScanDocument.create("sale");ScanDocument.append(d,"code",part());int committed=d.getInt("revision");ScanDocument.append(d,"code",part());JSONObject next=ScanDocument.afterCommit(d,committed);assertNotEquals(d.getString("id"),next.getString("id"));assertEquals(1,ScanDocument.items(next).getJSONObject(0).getInt("quantity"));}
 @Test public void unknownIsNotLostWhenKnownItemsCommit()throws Exception{JSONObject d=ScanDocument.create("receipt");ScanDocument.append(d,"code",part());ScanDocument.append(d,"unknown",null);JSONObject next=ScanDocument.afterCommit(d,d.getInt("revision"));assertEquals("unknown",ScanDocument.last(next).getString("code"));assertEquals(0,ScanDocument.items(next).length());}
}
